INSERT INTO public.texts (judul, konten) VALUES
(
  'Pentingnya Membaca Buku di Era Digital',
  'Membaca adalah jendela dunia yang membuka cakrawala pengetahuan tanpa batas bagi siapa saja yang menekuninya. Di tengah derasnya arus informasi digital dan media sosial saat ini, kebiasaan membaca buku sering kali mulai terabaikan. Padahal dengan membaca buku, seseorang tidak hanya memperoleh informasi baru, melainkan juga melatih konsentrasi, memperluas kosa kata, dan mengasah daya nalar kritis. Buku memberikan pemahaman yang mendalam terhadap suatu topik secara runtut dibandingkan potongan informasi singkat di internet. Oleh sebab itu, marilah kita senantiasa meluangkan waktu setiap hari untuk membaca. Jadikanlah membaca sebagai bagian dari gaya hidup agar generasi penerus bangsa memiliki wawasan luas serta budi pekerti yang luhur demi menyongsong masa depan yang gemilang.'
),
(
  'Keberagaman Budaya dan Persatuan Nusantara',
  'Indonesia merupakan negara kepulauan terbesar di dunia yang dianugerahi kekayaan alam melimpah serta keberagaman budaya yang tiada duanya. Dari Sabang sampai Merauke, terbentang ribuan pulau yang dihuni oleh ratusan suku bangsa dengan bahasa daerah, adat istiadat, tarian tradisional, serta rumah adat yang unik. Perbedaan yang ada bukanlah pemisah, melainkan kekayaan yang mempersatukan kita di bawah semboyan luhur Bhinneka Tunggal Ika. Sikap saling menghargai, gotong royong, dan toleransi antarwarga masyarakat adalah fondasi utama yang menjaga kedaulatan bangsa ini dari perpecahan. Kita sebagai generasi penerus memiliki tanggung jawab moral untuk melestarikan warisan budaya leluhur ini agar tidak tergerus oleh perkembangan zaman dan tetap menjadi kebanggaan di mata dunia internasional.'
),
(
  'Manfaat Olahraga Teratur bagi Kesehatan Tubuh',
  'Menjaga kesehatan tubuh merupakan investasi terbaik yang dapat kita lakukan demi menikmati kualitas hidup yang bahagia dan produktif. Salah satu cara paling efektif dan terjangkau untuk memelihara kebugaran fisik adalah dengan berolahraga secara teratur setiap minggunya. Melalui aktivitas fisik seperti berlari santai, berenang, bersepeda, ataupun senam kesegaran jasmani, sirkulasi darah menjadi lebih lancar dan fungsi jantung semakin kuat. Selain manfaat fisik, olahraga juga terbukti melepaskan hormon endorfin yang mampu meredakan stres mental serta meningkatkan suasana hati. Tubuh yang bugar membuat pikiran menjadi lebih segar sehingga kita dapat belajar dan bekerja dengan penuh konsentrasi. Mulailah membiasakan diri bergerak aktif sejak dini karena di dalam tubuh yang sehat terdapat jiwa yang kuat.'
),
(
  'Disiplin Waktu Kunci Utama Meraih Kesuksesan',
  'Waktu adalah anugerah paling berharga yang diberikan kepada setiap manusia dalam jumlah yang persis sama, yaitu dua puluh empat jam setiap hari. Akan tetapi, perbedaan hasil pencapaian antara orang yang sukses dan orang yang gagal terletak pada cara mereka mempergunakan waktu tersebut. Seseorang yang disiplin memahami betapa pentingnya menyusun skala prioritas dan tidak menunda pekerjaan yang seharusnya diselesaikan hari ini. Kebiasaan menunda hanya akan menumpuk beban tugas dan melahirkan kecemasan yang tidak perlu. Sebaliknya, membiasakan diri untuk selalu hadir tepat waktu serta menyelesaikan amanah sesuai jadwal akan membangun reputasi yang tepercaya di mata orang lain. Ingatlah bahwa waktu yang telah berlalu tidak akan pernah bisa diputar kembali untuk kedua kalinya.'
),
(
  'Peran Teknologi Komputer dalam Dunia Pendidikan',
  'Perkembangan teknologi informasi dan komunikasi telah membawa transformasi yang sangat revolusioner di dalam dunia pendidikan global masa kini. Jika dahulu kegiatan belajar mengajar hanya mengandalkan buku teks cetak dan papan tulis kapur, kini para siswa dapat mengakses ribuan materi pelajaran interaktif melalui internet. Komputer dan gawai cerdas memungkinkan kita untuk melakukan simulasi sains, belajar mengetik cepat dengan sistematis, serta berdiskusi dengan orang dari berbagai belahan dunia secara langsung. Namun demikian, teknologi hanyalah sebuah alat bantu perantara. Keberhasilan belajar tetap sangat bergantung pada kemauan belajar, rasa ingin tahu, dan integritas moral pengguna dalam memanfaatkannya secara bijaksana tanpa menyalahgunakan internet untuk hal-hal negatif yang merugikan diri sendiri.'
),
(
  'Menjaga Kebersihan dan Kelestarian Lingkungan Hidup',
  'Lingkungan hidup yang bersih dan asri merupakan syarat mutlak bagi terciptanya kehidupan masyarakat yang sehat dan terbebas dari berbagai penyakit menular. Sayangnya, permasalahan sampah plastik dan limbah rumah tangga masih menjadi tantangan besar di berbagai daerah pemukiman saat ini. Sampah yang dibuang sembarangan ke saluran air dapat menyumbat aliran sungai hingga memicu bencana banjir saat musim penghujan tiba. Oleh karena itu, kesadaran membuang sampah pada tempatnya serta menerapkan prinsip daur ulang harus ditanamkan sejak usia dini. Menanam pohon di pekarangan rumah juga turut membantu membersihkan udara dari polusi kendaraan bermotor. Marilah kita saling mengingatkan bahwa menjaga kelestarian alam ini adalah amanah besar untuk diwariskan kepada anak cucu di masa depan kelak.'
),
(
  'Kejujuran adalah Mahkota Perilaku yang Terpuji',
  'Kejujuran adalah nilai moral tertinggi yang menjadi tolok ukur kemuliaan akhlak dan kepribadian seseorang dalam pergaulan sehari-hari. Berkata jujur dan bertindak sesuai dengan kenyataan memang terkadang menuntut keberanian yang luar biasa, terutama saat menghadapi situasi yang penuh tekanan. Namun, sebuah kebohongan kecil akan senantiasa menuntut hadirnya kebohongan berikutnya hingga akhirnya menghancurkan kepercayaan orang lain secara permanen. Rasa percaya yang hilang sangatlah sulit untuk diperbaiki kembali meskipun dengan seribu kata permohonan maaf. Orang yang jujur akan senantiasa merasa tenang dan tenteram batinnya karena tidak ada beban dusta yang disembunyikan. Jadilah pribadi yang dapat diandalkan, amanah dalam setiap tugas, serta berani menjunjung kebenaran di manapun berada.'
),
(
  'Kekuatan Persahabatan dan Sikap Saling Menghargai',
  'Memiliki sahabat sejati merupakan salah satu anugerah paling indah dalam perjalanan hidup seseorang di dunia ini. Sahabat yang baik bukanlah mereka yang hanya ada ketika kita sedang bergembira, melainkan mereka yang rela mendampingi dan mengulurkan tangan ketika kita tertimpa cobaan berat. Dalam persahabatan yang tulus, perbedaan pandangan dan latar belakang sosial bukanlah penghalang untuk tetap saling mendukung satu sama lain. Setiap perselisihan kecil hendaknya diselesaikan dengan kepala dingin melalui dialog yang santun tanpa mengedepankan amarah. Rasa empati, kerendahan hati, serta kesetiaan adalah perekat abadi yang menjaga ikatan persahabatan tetap kokoh sepanjang masa. Hargailah teman-teman di sekitarmu dan berusahalah selalu menjadi pribadi yang membawa manfaat serta kebahagiaan bagi sesama.'
),
(
  'Pentingnya Sarapan Sehat Sebelum Memulai Beraktivitas',
  'Memulai hari dengan menyantap sarapan pagi yang bergizi seimbang merupakan langkah awal yang sangat penting bagi kesehatan tubuh setiap individu. Setelah beristirahat tidur sepanjang malam selama berjam-jam, kadar energi dan gula darah di dalam tubuh mengalami penurunan yang cukup signifikan. Sarapan memberikan pasokan glukosa yang sangat dibutuhkan oleh otak untuk bekerja, berpikir jernih, dan berkonsentrasi selama proses pembelajaran di sekolah. Anak-anak yang rutin sarapan pagi terbukti memiliki daya ingat yang lebih tajam dan tidak mudah merasa lelah ataupun mengantuk di kelas. Pilihlah menu sarapan yang kaya akan serat, karbohidrat kompleks, serta protein seperti telur, susu, dan buah-buahan segar agar stamina tubuh tetap terjaga optimal sepanjang hari.'
),
(
  'Semangat Pantang Menyerah Menghadapi Tantangan Hidup',
  'Perjalanan menuntut ilmu dan menggapai cita-cita luhur tidak akan pernah luput dari berbagai macam ujian, rintangan, dan kegagalan yang menguji mental kita. Kegagalan bukanlah tanda bahwa perjuangan harus berhenti seketika, melainkan sebuah pelajaran paling berharga untuk mengevaluasi kekurangan dan memperbaiki strategi yang salah. Para tokoh besar dunia yang berhasil mengukir prestasi gemilang adalah mereka yang pernah berkali-kali menemui kegagalan, namun tidak pernah membiarkan rasa putus asa menguasai tekad mereka. Semangat pantang menyerah, kerja keras tanpa kenal lelah, serta doa yang tulus adalah bahan bakar utama untuk melewati masa-masa sulit tersebut. Yakinlah bahwa setiap tetes keringat perjuangan hari ini akan membuahkan hasil manis yang membanggakan bagi diri sendiri, keluarga, dan bangsa di kemudian hari.'
)
ON CONFLICT DO NOTHING;
